package com.bank.cohort;

import java.time.LocalDate;
import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class JoiningYearDemo {
    private static final Logger log = Logger.getLogger("Cohort");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", LocalDate.parse("2020-01-15")),
            new Employee("Priya", LocalDate.parse("2020-07-01")),
            new Employee("Amit", LocalDate.parse("2022-03-10")));
        CohortService service = new CohortService();

        Map<Integer, List<String>> cohorts = service.byJoiningYear(staff);
        cohorts.forEach((year, names) -> log.info(() -> year + " → " + names));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final LocalDate joinDate;
    Employee(String name, LocalDate joinDate) { this.name = name; this.joinDate = joinDate; }
    String getName() { return name; }
    LocalDate getJoinDate() { return joinDate; }
}

// ─── Would be in service/CohortService.java ───
class CohortService {
    Map<Integer, List<String>> byJoiningYear(List<Employee> staff) {
        return staff.stream()
            .filter(e -> e.getJoinDate() != null)            // guard null dates
            .collect(groupingBy(
                e -> e.getJoinDate().getYear(),               // classifier: year
                TreeMap::new,                                 // chronological keys
                mapping(Employee::getName, toList())));        // store names
    }
}
